def loud_and_rich(richer, quiet):
    n = len(quiet)
    graph = [[] for _ in range(n)]
    for a, b in richer:
        graph[b].append(a)  # b -> a: a is richer than b

    answer = [-1] * n

    def dfs(person):
        if answer[person] != -1:
            return answer[person]
        best = person
        for richer_person in graph[person]:
            candidate = dfs(richer_person)
            if quiet[candidate] < quiet[best]:
                best = candidate
        answer[person] = best
        return best

    for person in range(n):
        dfs(person)

    return answer

